/**
 * Safari Magic Gallery — retro pixel art gallery logic.
 *
 * Data comes from community_registry.json, which is generated by
 * build_registry.py. Presentation fields (art_image, tags, category, featured)
 * are curated in web/registry_curation.json, so this file renders the registry
 * as-is rather than guessing from extension names.
 */

// State
let extensions = [];
let activeCategory = 'all';
let featuredExtension = null;
let lastFocusedElement = null;

// Layout
const bentoGrid = document.getElementById('bento-cards-grid');
const ribbonButtons = document.querySelectorAll('.ribbon-icon-btn');
const toastEl = document.getElementById('toast');

// Featured card
const featuredImg = document.getElementById('featured-img');
const featuredCreator = document.getElementById('featured-creator');
const featuredTitle = document.getElementById('featured-title');
const featuredSaveBtn = document.getElementById('featured-save-btn');
const featuredInspectBtn = document.getElementById('featured-inspect-btn');
const featuredHeartBtn = document.getElementById('featured-heart-btn');

// Inspector modal
const inspectorModal = document.getElementById('inspector-modal');
const closeInspectorBtn = document.getElementById('close-inspector-btn');
const modalTitle = document.getElementById('modal-title');
const modalAuthor = document.getElementById('modal-author');
const modalCategory = document.getElementById('modal-category');
const modalImg = document.getElementById('modal-img');
const modalDescription = document.getElementById('modal-description');
const modalPrompt = document.getElementById('modal-prompt');
const modalCliCmd = document.getElementById('modal-cli-cmd');
const modalDownloadPkgBtn = document.getElementById('modal-download-pkg-btn');
const copyModalPromptBtn = document.getElementById('copy-modal-prompt-btn');
const copyModalCliBtn = document.getElementById('copy-modal-cli-btn');

// Submit modal
const submitModal = document.getElementById('submit-modal');
const openSubmitModalBtn = document.getElementById('open-submit-modal-btn');
const heroBecomeAuthorBtn = document.getElementById('hero-become-author-btn');
const closeSubmitBtn = document.getElementById('close-submit-btn');

const copyCliCommandBtn = document.getElementById('copy-cli-command-btn');

const PLACEHOLDER_ART = 'assets/hero_cyberpunk.jpg';

/**
 * Load the registry and render the gallery.
 */
async function initGallery() {
  setupEventListeners();

  try {
    const res = await fetch('community_registry.json', { cache: 'no-cache' });
    if (!res.ok) {
      throw new Error(`registry responded ${res.status}`);
    }
    const data = await res.json();
    extensions = Array.isArray(data.extensions) ? data.extensions : [];
  } catch (err) {
    // Serving over file:// blocks fetch, which is the usual cause here.
    renderLoadError(err);
    return;
  }

  if (extensions.length === 0) {
    renderEmptyState();
    return;
  }

  featuredExtension = extensions.find(ext => ext.featured) || extensions[0];
  setupFeaturedCard(featuredExtension);
  renderBentoGrid();
}

/**
 * Categories an extension can be filtered by: its tags plus its category.
 */
function categoriesFor(ext) {
  const values = Array.isArray(ext.tags) ? [...ext.tags] : [];
  if (ext.category) values.push(ext.category);
  return values.map(v => String(v).toLowerCase());
}

/**
 * Only allow same-origin relative paths from the registry into href/src.
 */
function safeUrl(url) {
  if (!url) return '';
  const value = String(url);
  if (/^(https?:)?\/\//i.test(value) || value.startsWith('/')) return value;
  if (/^[a-z][a-z0-9+.-]*:/i.test(value)) return ''; // reject javascript:, data:, etc.
  return value;
}

function artFor(ext) {
  return safeUrl(ext.art_image) || PLACEHOLDER_ART;
}

function setupFeaturedCard(ext) {
  if (!ext) return;
  featuredExtension = ext;

  featuredImg.src = artFor(ext);
  featuredImg.alt = ext.name;
  featuredCreator.textContent = ext.author ? `@${ext.author}` : 'community';
  featuredTitle.textContent = ext.name;

  const download = safeUrl(ext.download_url);
  featuredSaveBtn.href = download;
  featuredSaveBtn.setAttribute('aria-label', `Download ${ext.name}`);

  featuredInspectBtn.onclick = () => openInspector(ext);
  featuredImg.onclick = () => openInspector(ext);
  featuredImg.style.cursor = 'pointer';
}

function renderBentoGrid() {
  const filtered = extensions.filter(ext => {
    if (activeCategory === 'all') return true;
    return categoriesFor(ext).includes(activeCategory);
  });

  if (filtered.length === 0) {
    bentoGrid.innerHTML =
      '<p class="grid-empty-note">No extensions in this category yet.</p>';
    return;
  }

  bentoGrid.innerHTML = filtered.slice(0, 6).map(ext => `
    <div class="grid-card-item" data-id="${escapeHTML(ext.id)}" role="button" tabindex="0"
         aria-label="Inspect ${escapeHTML(ext.name)}">
      <img src="${escapeHTML(artFor(ext))}" alt="${escapeHTML(ext.name)}" class="grid-card-thumb" loading="lazy">
      <div class="grid-card-overlay">
        <div class="grid-card-title">${escapeHTML(ext.name)}</div>
        <div class="grid-card-author">by @${escapeHTML(ext.author || 'community')}</div>
      </div>
    </div>
  `).join('');

  bentoGrid.querySelectorAll('.grid-card-item').forEach(card => {
    const open = () => {
      const item = extensions.find(e => e.id === card.getAttribute('data-id'));
      if (item) openInspector(item);
    };
    card.addEventListener('click', open);
    card.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        open();
      }
    });
  });
}

function renderLoadError(err) {
  console.error('Could not load community_registry.json:', err);
  bentoGrid.innerHTML = `
    <p class="grid-empty-note">
      Could not load the extension catalog.<br>
      Serve this folder over HTTP: <code>python3 -m http.server 8000 --directory web</code>
    </p>`;
}

function renderEmptyState() {
  bentoGrid.innerHTML =
    '<p class="grid-empty-note">No extensions published yet. Be the first to submit one!</p>';
}

function openInspector(ext) {
  modalTitle.textContent = ext.name;
  modalAuthor.textContent = `crafted by @${ext.author || 'community'}`;
  modalCategory.textContent = (ext.category || 'extension').toUpperCase();
  modalImg.src = artFor(ext);
  modalImg.alt = ext.name;
  modalDescription.textContent = ext.description || 'Safari AI Magic Extension';
  modalPrompt.textContent = ext.prompt ? `"${ext.prompt}"` : '"No AI prompt provided."';

  // Registry IDs are already CLI-safe slugs.
  const cliCommand = `safari-magic-ext install ${ext.id}`;
  modalCliCmd.textContent = cliCommand;

  const download = safeUrl(ext.download_url);
  modalDownloadPkgBtn.href = download;
  modalDownloadPkgBtn.download = download.split('/').pop() || `${ext.name}.magicext`;

  copyModalPromptBtn.onclick = () =>
    copyText(ext.prompt, 'AI Prompt copied! Paste in Safari to remix.');
  copyModalCliBtn.onclick = () => copyText(cliCommand, 'CLI install command copied!');

  openModal(inspectorModal);
}

/**
 * Modal helpers: track focus so keyboard users are not stranded.
 */
function openModal(modal) {
  lastFocusedElement = document.activeElement;
  modal.classList.remove('hidden');
  modal.removeAttribute('aria-hidden');
  const focusTarget = modal.querySelector('button, [href], input, textarea');
  if (focusTarget) focusTarget.focus();
}

function closeModal(modal) {
  modal.classList.add('hidden');
  modal.setAttribute('aria-hidden', 'true');
  if (lastFocusedElement && typeof lastFocusedElement.focus === 'function') {
    lastFocusedElement.focus();
    lastFocusedElement = null;
  }
}

function setupEventListeners() {
  ribbonButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      ribbonButtons.forEach(b => {
        b.classList.remove('active');
        b.setAttribute('aria-pressed', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-pressed', 'true');
      activeCategory = (btn.getAttribute('data-filter') || 'all').toLowerCase();
      renderBentoGrid();
    });
  });

  if (featuredHeartBtn) {
    featuredHeartBtn.addEventListener('click', () => {
      featuredHeartBtn.classList.toggle('liked');
      const liked = featuredHeartBtn.classList.contains('liked');
      featuredHeartBtn.setAttribute('aria-pressed', String(liked));
      if (liked) showToast('Added to favorites! ❤️');
    });
  }

  if (copyCliCommandBtn) {
    copyCliCommandBtn.addEventListener('click', () => {
      // Use whatever is actually featured rather than a hardcoded slug.
      const id = featuredExtension ? featuredExtension.id : '<extension-id>';
      copyText(`safari-magic-ext install ${id}`, 'Terminal command copied!');
    });
  }

  closeInspectorBtn.addEventListener('click', () => closeModal(inspectorModal));
  inspectorModal.addEventListener('click', e => {
    if (e.target === inspectorModal) closeModal(inspectorModal);
  });

  if (openSubmitModalBtn) {
    openSubmitModalBtn.addEventListener('click', () => openModal(submitModal));
  }
  if (heroBecomeAuthorBtn) {
    heroBecomeAuthorBtn.addEventListener('click', () => openModal(submitModal));
  }
  if (closeSubmitBtn) {
    closeSubmitBtn.addEventListener('click', () => closeModal(submitModal));
  }
  submitModal.addEventListener('click', e => {
    if (e.target === submitModal) closeModal(submitModal);
  });

  document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    if (!inspectorModal.classList.contains('hidden')) closeModal(inspectorModal);
    if (!submitModal.classList.contains('hidden')) closeModal(submitModal);
  });
}

function copyText(text, successMsg) {
  if (!text) return;

  const fallback = () => {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.position = 'absolute';
    ta.style.left = '-9999px';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    showToast(successMsg || 'Copied to clipboard!');
  };

  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard
      .writeText(text)
      .then(() => showToast(successMsg || 'Copied to clipboard!'))
      .catch(fallback);
  } else {
    fallback();
  }
}

let toastTimer = null;
function showToast(msg) {
  toastEl.textContent = msg;
  toastEl.classList.remove('hidden');
  if (toastTimer) clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toastEl.classList.add('hidden'), 2200);
}

function escapeHTML(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

document.addEventListener('DOMContentLoaded', initGallery);
